package main

import (
	"bytes"
	"debug/elf"
	"encoding/binary"
	"fmt"
)

type ELFFile struct {
	Bytes      []byte
	Class      uint8
	Data       uint8
	Order      binary.ByteOrder
	HeaderSize uint64
	Header     ELFHeader
	Segments   []ProgramHeader
	Sections   []SectionHeader
}

type ELFHeader struct {
	Type      uint16
	Machine   uint16
	Version   uint32
	Entry     uint64
	Phoff     uint64
	Shoff     uint64
	Flags     uint32
	Ehsize    uint16
	Phentsize uint16
	Phnum     uint16
	Shentsize uint16
	Shnum     uint16
	Shstrndx  uint16
}

type ProgramHeader struct {
	Index       int
	Type        uint32
	Flags       uint32
	Offset      uint64
	Vaddr       uint64
	Paddr       uint64
	Filesz      uint64
	Memsz       uint64
	Align       uint64
	NoteEntries []Note
}

type SectionHeader struct {
	Index     int
	Name      string
	NameOff   uint32
	Type      uint32
	Flags     uint64
	Addr      uint64
	Offset    uint64
	Size      uint64
	Link      uint32
	Info      uint32
	Addralign uint64
	Entsize   uint64
}

type Note struct {
	Name string
	Type uint32
	Desc []byte
}

func ParseELF(data []byte) (*ELFFile, error) {
	if len(data) < 16 {
		return nil, fmt.Errorf("file is smaller than ELF header's e_ident")
	}

	if !bytes.Equal(data[:4], []byte{0x7f, 'E', 'L', 'F'}) {
		return nil, fmt.Errorf("mismatched magic: not an ELF file")
	}

	class := data[4]
	var headerSize uint64
	switch class {
	case byte(elf.ELFCLASS32):
		headerSize = 52
	case byte(elf.ELFCLASS64):
		headerSize = 64
	default:
		return nil, fmt.Errorf("Unknown bitness: %d", class)
	}

	var order binary.ByteOrder
	switch data[5] {
	case byte(elf.ELFDATA2LSB):
		order = binary.LittleEndian
	case byte(elf.ELFDATA2MSB):
		order = binary.BigEndian
	default:
		return nil, fmt.Errorf("Unknown endianness: %d", data[5])
	}

	if uint64(len(data)) < headerSize {
		return nil, fmt.Errorf("file is smaller than ELF file header")
	}

	hdr := ELFHeader{}
	if class == byte(elf.ELFCLASS32) {
		hdr.Type = order.Uint16(data[16:18])
		hdr.Machine = order.Uint16(data[18:20])
		hdr.Version = order.Uint32(data[20:24])
		hdr.Entry = uint64(order.Uint32(data[24:28]))
		hdr.Phoff = uint64(order.Uint32(data[28:32]))
		hdr.Shoff = uint64(order.Uint32(data[32:36]))
		hdr.Flags = order.Uint32(data[36:40])
		hdr.Ehsize = order.Uint16(data[40:42])
		hdr.Phentsize = order.Uint16(data[42:44])
		hdr.Phnum = order.Uint16(data[44:46])
		hdr.Shentsize = order.Uint16(data[46:48])
		hdr.Shnum = order.Uint16(data[48:50])
		hdr.Shstrndx = order.Uint16(data[50:52])
	} else {
		hdr.Type = order.Uint16(data[16:18])
		hdr.Machine = order.Uint16(data[18:20])
		hdr.Version = order.Uint32(data[20:24])
		hdr.Entry = order.Uint64(data[24:32])
		hdr.Phoff = order.Uint64(data[32:40])
		hdr.Shoff = order.Uint64(data[40:48])
		hdr.Flags = order.Uint32(data[48:52])
		hdr.Ehsize = order.Uint16(data[52:54])
		hdr.Phentsize = order.Uint16(data[54:56])
		hdr.Phnum = order.Uint16(data[56:58])
		hdr.Shentsize = order.Uint16(data[58:60])
		hdr.Shnum = order.Uint16(data[60:62])
		hdr.Shstrndx = order.Uint16(data[62:64])
	}

	ef := &ELFFile{
		Bytes:      data,
		Class:      class,
		Data:       data[5],
		Order:      order,
		HeaderSize: headerSize,
		Header:     hdr,
