				ph.Offset = uint64(order.Uint32(entry[4:8]))
				ph.Vaddr = uint64(order.Uint32(entry[8:12]))
				ph.Paddr = uint64(order.Uint32(entry[12:16]))
				ph.Filesz = uint64(order.Uint32(entry[16:20]))
				ph.Memsz = uint64(order.Uint32(entry[20:24]))
				ph.Flags = order.Uint32(entry[24:28])
				ph.Align = uint64(order.Uint32(entry[28:32]))
			} else {
				ph.Type = order.Uint32(entry[0:4])
				ph.Flags = order.Uint32(entry[4:8])
				ph.Offset = order.Uint64(entry[8:16])
				ph.Vaddr = order.Uint64(entry[16:24])
				ph.Paddr = order.Uint64(entry[24:32])
				ph.Filesz = order.Uint64(entry[32:40])
				ph.Memsz = order.Uint64(entry[40:48])
				ph.Align = order.Uint64(entry[48:56])
			}
			if ph.Type == uint32(elf.PT_NOTE) {
				if blob, ok := sliceRange(data, ph.Offset, ph.Filesz); ok {
					ph.NoteEntries = parseNotes(blob)
				}
			}
			ef.Segments = append(ef.Segments, ph)
		}
	}

	sectEntrySize := uint64(hdr.Shentsize)
	minSectSize := uint64(64)
	if class == byte(elf.ELFCLASS32) {
		minSectSize = 40
	}
	if hdr.Shnum > 0 {
		if sectEntrySize < minSectSize {
			return nil, fmt.Errorf("section header entry is too small")
		}
		if err := checkTableBounds(uint64(len(data)), hdr.Shoff, sectEntrySize, uint64(hdr.Shnum), "section"); err != nil {
			return nil, err
		}
		ef.Sections = make([]SectionHeader, 0, int(hdr.Shnum))
		for i := 0; i < int(hdr.Shnum); i++ {
			off := hdr.Shoff + uint64(i)*sectEntrySize
			entry := data[off : off+sectEntrySize]
			sh := SectionHeader{Index: i}
			if class == byte(elf.ELFCLASS32) {
				sh.NameOff = order.Uint32(entry[0:4])
				sh.Type = order.Uint32(entry[4:8])
				sh.Flags = uint64(order.Uint32(entry[8:12]))
				sh.Addr = uint64(order.Uint32(entry[12:16]))
				sh.Offset = uint64(order.Uint32(entry[16:20]))
				sh.Size = uint64(order.Uint32(entry[20:24]))
				sh.Link = order.Uint32(entry[24:28])
				sh.Info = order.Uint32(entry[28:32])
				sh.Addralign = uint64(order.Uint32(entry[32:36]))
				sh.Entsize = uint64(order.Uint32(entry[36:40]))
			} else {
				sh.NameOff = order.Uint32(entry[0:4])
				sh.Type = order.Uint32(entry[4:8])
				sh.Flags = order.Uint64(entry[8:16])
				sh.Addr = order.Uint64(entry[16:24])
				sh.Offset = order.Uint64(entry[24:32])
				sh.Size = order.Uint64(entry[32:40])
				sh.Link = order.Uint32(entry[40:44])
				sh.Info = order.Uint32(entry[44:48])
				sh.Addralign = order.Uint64(entry[48:56])
				sh.Entsize = order.Uint64(entry[56:64])
			}
			ef.Sections = append(ef.Sections, sh)
		}
	}

	if int(hdr.Shstrndx) < len(ef.Sections) {
		shstr := ef.Sections[int(hdr.Shstrndx)]
		if blob, ok := ef.sectionData(shstr); ok {
			for i := range ef.Sections {
				ef.Sections[i].Name = stringFromTable(blob, ef.Sections[i].NameOff)
			}
		}
	}

	return ef, nil
}

func checkTableBounds(fileSize, off, entrySize, count uint64, kind string) error {
	if off > fileSize {
		return fmt.Errorf("%s header table is outside the file", kind)
	}
	if count == 0 {
		return nil
	}
	size := entrySize * count
	if off+size < off || off+size > fileSize {
		return fmt.Errorf("%s header table is outside the file", kind)
	}
	return nil
}

