func sliceRange(data []byte, off, size uint64) ([]byte, bool) {
	if off > uint64(len(data)) {
		return nil, false
	}
	if size == 0 {
		return []byte{}, true
	}
	end := off + size
	if end < off || end > uint64(len(data)) {
		return nil, false
	}
	return data[off:end], true
}

func (ef *ELFFile) sectionData(sh SectionHeader) ([]byte, bool) {
	if sh.Type == uint32(elf.SHT_NOBITS) {
		return nil, false
	}
	return sliceRange(ef.Bytes, sh.Offset, sh.Size)
}

func parseNotes(data []byte) []Note {
	notes := make([]Note, 0)
	for off := 0; off+12 <= len(data); {
		namesz := int(binary.LittleEndian.Uint32(data[off : off+4]))
		descsz := int(binary.LittleEndian.Uint32(data[off+4 : off+8]))
		typ := binary.LittleEndian.Uint32(data[off+8 : off+12])
		off += 12

		if namesz < 0 || descsz < 0 {
			break
		}
		if off+namesz > len(data) {
			break
		}
		nameBytes := data[off : off+namesz]
		off += align4(namesz)
		if off > len(data) || off+descsz > len(data) {
			break
		}
		descBytes := append([]byte(nil), data[off:off+descsz]...)
		off += align4(descsz)

		notes = append(notes, Note{
			Name: trimCString(nameBytes),
			Type: typ,
			Desc: descBytes,
		})
	}
	return notes
}

func align4(n int) int {
	return (n + 3) &^ 3
}

func trimCString(data []byte) string {
	if idx := bytes.IndexByte(data, 0); idx >= 0 {
		return string(data[:idx])
	}
	return string(data)
}

func stringFromTable(tab []byte, off uint32) string {
	if int(off) >= len(tab) {
		return ""
	}
	chunk := tab[off:]
	if idx := bytes.IndexByte(chunk, 0); idx >= 0 {
		return string(chunk[:idx])
	}
	return string(chunk)
