func formatSummaryFileSize(size uint64) string {
	if size < 1024 {
		return fmt.Sprintf("%d B", size)
	}
	return fmt.Sprintf("%s (%d B)", humanizeBinary(size), size)
}

func formatDataSize(size uint64) string {
	if size < 1024 {
		return fmt.Sprintf("%d", size)
	}
	return fmt.Sprintf("%d (%s)", size, humanizeBinary(size))
}

func humanizeBinary(size uint64) string {
	units := []string{"KiB", "MiB", "GiB", "TiB", "PiB", "EiB"}
	value := float64(size)
	unit := -1
	for value >= 1024 && unit < len(units)-1 {
		value /= 1024
		unit++
	}
	if unit < 0 {
		return fmt.Sprintf("%d B", size)
	}
	return fmt.Sprintf("%.1f %s", value, units[unit])
}

func hexValue(v uint64) string {
	return fmt.Sprintf("0x%x", v)
}

func decNumberSpan(v uint64) string {
	return fmt.Sprintf("<span class='number' title='%s'>%d</span>", hexValue(v), v)
}

func decNumberSpanClass(v uint64, class string) string {
	return fmt.Sprintf("<span title='%s' class='number %s'>%d</span>", hexValue(v), class, v)
}

func hexNumberSpan(v uint64) string {
	return fmt.Sprintf("<span class='number' title='%d'>%s</span>", v, hexValue(v))
}

func dataSizeSpan(v uint64) string {
	return fmt.Sprintf("<span class='number' title='%s'>%s</span>", hexValue(v), formatDataSize(v))
}

func stringTableEntries(data []byte) []string {
	entries := make([]string, 0)
	start := 0
	for i, b := range data {
		if b != 0 {
			continue
		}
		if i > start {
			entries = append(entries, string(data[start:i]))
		}
		start = i + 1
	}
	if start < len(data) {
		entries = append(entries, string(data[start:]))
	}
	return entries
}

func asciiByte(b byte) string {
	if b < 0x21 || b > 0x7e {
		return "."
	}
	switch b {
	case '&':
		return "&amp;"
	case '<':
		return "&lt;"
	case '>':
		return "&gt;"
	case '"':
		return "&quot;"
	case '\'':
		return "&apos;"
	default:
		return string(b)
	}
}

